"use client"

import React, { useState } from "react"
import { useRouter } from "next/navigation"
import Link from "next/link"
import LoginForm from "../components/LoginForm"
import styles from "../pages/login/login.module.css"
import { login } from "../lib/auth"
import fetcher from "../lib/fetcher"

type FormData = {
  email: string
  password: string
}

export default function LoginPage() {
  const router = useRouter()
  const [loading, setLoading] = useState(false)

  async function handleSubmit(data: FormData) {
    setLoading(true)
    try {
      // 1. ログイン API 呼び出し
      const res = await login(data.email, data.password)

      // 2. トークンを保存
      localStorage.setItem("token", res.token)
      localStorage.setItem("refreshToken", res.refreshToken)

      // 3. ユーザー情報取得（管理者判定含む）
      const me = await fetcher<{ id: number; username: string; email: string; displayName: string; roles?: string[]; isAdmin?: boolean }>("/api/v1/users/me")

      // 4. ユーザー情報をストレージへ保存（管理者フラグ含む）
      localStorage.setItem("currentUser", JSON.stringify(me))

      router.push("/dashboard")
    } catch (err: any) {
      // LoginForm 内の serverError に伝播させる
      throw new Error(err?.message || "ネットワークエラーが発生しました。")
    } finally {
      setLoading(false)
    }
  }

  return (
    <div className={styles.container}>
      <div className={styles.centerCard}>
        <div className={styles.cardTop}>
          <img
            src="/images/NaviAI_logo_gradient.svg"
            alt="NaviAI ロゴ"
            className={styles.brandLogo}
          />
          <div className={styles.cardTitle}>team sharing</div>
        </div>

        <div className={styles.cardBody}>
          <div className={styles.formWrap}>
            <LoginForm onSubmit={handleSubmit} loading={loading} />
          </div>

          <div className={styles.helpBox}>
            <div>まだアカウントをお持ちでないですか？</div>
            <div className={styles.helpSub}>
              <Link href="/register" className={styles.helpLink}>
                アカウント登録はこちら
              </Link>
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}

.container {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 48px 16px;
  background: linear-gradient(180deg, #dbefff 0%, #c3ddff 100%);
}

.title {
  font-size: 1.75rem;
  margin: 0 0 12px 0;
  text-align: center;
  color: #071431;
  font-weight: 700;
}

.centerCard {
  width: 100%;
  max-width: 760px;
  border-radius: 28px;
  overflow: hidden;
  box-shadow: 0 12px 40px rgba(11,95,255,0.12);
  background: linear-gradient(180deg,#6fb1ff 0%,#86b9ff 100%);
}

.cardTop {
  padding: 28px 40px;
  background: linear-gradient(180deg, rgba(255,255,255,0.06), transparent 40%);
  position: relative;
}

.headerIllustration {
  width: 320px;
  height: 88px;
  margin: 0 auto 8px auto;
  border-radius: 12px;
  background: radial-gradient(circle at 30% 30%, rgba(255,255,255,0.7), transparent 20%), radial-gradient(circle at 70% 30%, rgba(255,255,255,0.5), transparent 15%);
  opacity: 0.9;
}

.brandLogo {
  display: block;
  width: min(320px, 100%);
  height: auto;
  margin: 0 auto 10px auto;
}

.cardTitle {
  text-align: center;
  color: #ffffff;
  font-size: 22px;
  font-weight: 700;
  margin-top: 6px;
}

.cardBody {
  background: linear-gradient(180deg,#6fb1ff 0%,#86b9ff 100%);
  padding: 32px 40px 40px 40px;
  color: #ffffff;
}

.formWrap {
  width: 100%;
  max-width: 560px;
  margin: 0 auto 8px auto;
}

.form {
  display: flex;
  flex-direction: column;
}

.field {
  margin-bottom: 14px;
}

.label {
  display: block;
  margin-bottom: 8px;
  font-weight: 700;
  color: #ffffff;
}

.input {
  width: 100%;
  padding: 14px 16px;
  border: 1px solid #e6eefb;
  border-radius: 28px;
  font-size: 1rem;
  transition: box-shadow 0.12s ease, border-color 0.12s ease;
  background: #ffffff;
}

.input:focus {
  outline: none;
  border-color: #7fb5ff;
  box-shadow: 0 6px 20px rgba(11,95,255,0.12);
}

.toggleButton {
  padding: 10px 12px;
  background: #eef2ff;
  border: 1px solid #dbeafe;
  border-radius: 8px;
  color: #0b5fff;
  cursor: pointer;
}

.button {
  width: 100%;
  padding: 14px 18px;
  background: linear-gradient(180deg,#f79b3b,#f36e2b);
  color: #fff;
  border: none;
  border-radius: 34px;
  cursor: pointer;
  font-weight: 800;
  font-size: 1.05rem;
}

.button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.error {
  color: #b00020;
  margin-bottom: 12px;
  font-weight: 600;
}

.meta a { color: #0b5fff }

.fieldError {
  color: #b00020;
  margin-top: 6px;
  font-size: 0.875rem;
}

.helpBox {
  margin: 18px auto 0 auto;
  max-width: 560px;
  background: #d9e9ff;
  border-radius: 12px;
  padding: 14px 18px;
  text-align: center;
  color: #2b4f74;
}

.helpSub { margin-top: 6px }

.helpLink {
  color: #0b5fff;
  font-weight: 600;
  text-decoration: underline;
}

.fieldHint {
  font-size: 0.8rem;
  font-weight: 400;
  margin-left: 6px;
  opacity: 0.85;
}

.successMessage {
  background: #d4f0d4;
  border: 1px solid #5bb85b;
  border-radius: 8px;
  color: #1a5c1a;
  padding: 12px 16px;
  margin-bottom: 12px;
  font-size: 0.9rem;
  line-height: 1.5;
}

.pageHeading {
  text-align: center;
  color: #ffffff;
  font-size: 1.3rem;
  font-weight: 700;
  margin: 0 0 20px 0;
}

